const A4W=794,A4H=1123,PPAD=30,PFOOT=28;
function pdfTitle(){if(V.v=='all'&&V.am!='ph')return 'تجميع كل الصيدليات — '+((V.q&&V.q.mo)||'كل الشهور');const p=curP();return (p?'صيدلية '+p.no+' — ':'')+({print:'ملخص للطباعة',mgmt:'تقرير تنفيذ للإدارة',ck:'Checklist الاستلام'}[V.sm]||'')}
function pdfClone(src){const c=(src||$('#rp')).cloneNode(true);c.querySelectorAll('details').forEach(d=>d.setAttribute('open',''));c.querySelectorAll('.np,.hint').forEach(e=>e.remove());
 c.querySelectorAll('[contenteditable]').forEach(e=>e.removeAttribute('contenteditable'));
 c.querySelectorAll('table').forEach(t=>{const h=t.rows[0];if(!h)return;const l=h.cells[h.cells.length-1];if(l&&l.tagName=='TH'&&l.textContent.trim()=='إجراء')[...t.rows].forEach(r=>{if(r.cells.length)r.deleteCell(r.cells.length-1)})});
 c.querySelectorAll('.fm,button,script').forEach(e=>e.remove());
 c.querySelectorAll('input,textarea,select').forEach(i=>{const e=document.createElement('span');if(i.type=='checkbox'){e.className='cbx'+(i.checked?' on':'');e.textContent=i.checked?'✓':''}else{e.textContent=(i.tagName=='SELECT'?(i.options[i.selectedIndex]||{}).text:i.value)||'—';e.style.cssText='color:#1B2430;font-weight:700;font-size:13px'+(i.tagName=='TEXTAREA'?';white-space:pre-wrap;display:block':'')}i.replaceWith(e)});
 c.querySelectorAll('.tt').forEach(e=>{if(!e.textContent.trim())e.remove()});
 return c}
function pdfLayout(src0,ttl){const src=pdfClone(src0);trNode(src);const host=document.createElement('div');host.style.cssText='position:fixed;left:-30000px;top:0;width:'+A4W+'px';document.body.appendChild(host);
 const pages=[],MAX=A4H-PPAD-PFOOT;let body;
 const np=()=>{const pg=document.createElement('div');pg.className='pdfpg';pg.style.direction=isEN()?'ltr':'rtl';body=document.createElement('div');body.className='pdfbd';pg.appendChild(body);host.appendChild(pg);pages.push(pg)};
 const fits=()=>body.offsetHeight<=MAX;
 const carry=()=>{const pv=body.lastElementChild;if(pv&&pv.tagName=='H3'&&body.children.length>1){body.removeChild(pv);return pv}return null};
 np();
 for(const blk of [...src.children]){body.appendChild(blk);if(fits())continue;body.removeChild(blk);
  const tb=blk.tagName=='TABLE'?blk:(blk.children.length==1&&blk.firstElementChild.tagName=='TABLE'?blk.firstElementChild:null);
  if(tb&&tb.tBodies.length){const head=tb.tHead,rows=[...tb.tBodies].flatMap(b=>[...b.rows]);
   const mk=()=>{const t=tb.cloneNode(false);if(head)t.appendChild(head.cloneNode(true));const bd=document.createElement('tbody');t.appendChild(bd);let el=t;if(blk!==tb){el=blk.cloneNode(false);el.appendChild(t)}return{el,bd}};
   let cur=mk();body.appendChild(cur.el);
   for(const r of rows){cur.bd.appendChild(r);if(fits())continue;
    if(cur.bd.rows.length==1&&body.children.length==1)continue;
    cur.bd.removeChild(r);
    if(!cur.bd.rows.length){body.removeChild(cur.el);const c=carry();np();if(c)body.appendChild(c)}else np();
    cur=mk();body.appendChild(cur.el);cur.bd.appendChild(r)}
  }else{if(body.children.length){const c=carry();np();if(c)body.appendChild(c)}body.appendChild(blk)}}
 const tt=esc(ttl||pdfTitle()),dt=new Date().toLocaleDateString('en-GB');
 pages.forEach((pg,i)=>{const f=document.createElement('div');f.className='pdfft';f.innerHTML=tr(`<span>${tt} · ${dt}</span><span>صفحة ${i+1} من ${pages.length}</span>`);pg.appendChild(f)});
 return{host,pages}}
let CSSX=null;
function pgJpeg(pg,sc){CSSX=CSSX||[...document.querySelectorAll('style')].map(x=>x.textContent).join('\n');
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${A4W}" height="${A4H}"><foreignObject x="0" y="0" width="${A4W}" height="${A4H}"><div xmlns="http://www.w3.org/1999/xhtml" dir="${isEN()?'ltr':'rtl'}"><style><![CDATA[${CSSX}]]></style>${new XMLSerializer().serializeToString(pg)}</div></foreignObject></svg>`;
 return new Promise((ok,no)=>{const im=new Image();im.onload=()=>setTimeout(()=>{try{const cv=document.createElement('canvas');cv.width=Math.round(A4W*sc);cv.height=Math.round(A4H*sc);const x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,cv.width,cv.height);x.drawImage(im,0,0,cv.width,cv.height);const d=atob(cv.toDataURL('image/jpeg',0.8).split(',')[1]),u=new Uint8Array(d.length);for(let i=0;i<d.length;i++)u[i]=d.charCodeAt(i);ok({w:cv.width,h:cv.height,b:u})}catch(e){no(e)}},40);im.onerror=()=>no(new Error('svg render failed'));im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)})}
function mkPdf(imgs){const E=new TextEncoder(),parts=[],off=[];let len=0;const add=x=>{const u=typeof x=='string'?E.encode(x):x;parts.push(u);len+=u.length};
 const obj=(n,str,bin)=>{off[n]=len;add(n+' 0 obj\n'+str);if(bin){add(bin);add('\nendstream')}add('\nendobj\n')};
 const N=2+imgs.length*3;add('%PDF-1.4\n%âãÏÓ\n');
 obj(1,'<< /Type /Catalog /Pages 2 0 R >>');
 obj(2,'<< /Type /Pages /Kids ['+imgs.map((_,i)=>(3+3*i)+' 0 R').join(' ')+'] /Count '+imgs.length+' >>');
 imgs.forEach((m,i)=>{const p=3+3*i,c='q 595.28 0 0 841.89 0 0 cm /Im0 Do Q';
  obj(p,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 '+(p+2)+' 0 R >> >> /Contents '+(p+1)+' 0 R >>');
  obj(p+1,'<< /Length '+c.length+' >>\nstream\n'+c+'\nendstream');
  obj(p+2,'<< /Type /XObject /Subtype /Image /Width '+m.w+' /Height '+m.h+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+m.b.length+' >>\nstream\n',m.b)});
 const x=len;add('xref\n0 '+(N+1)+'\n0000000000 65535 f \n'+off.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size '+(N+1)+' /Root 1 0 R >>\nstartxref\n'+x+'\n%%EOF');
 return new Blob(parts,{type:'application/pdf'})}
function remToast(m,a,l){const t=toast(`<span>${m}</span><button class="pr" ${a}="1">${l}</button><button data-tclose="1">لاحقًا</button>`);t.classList.add('rem');return t}
function toast(h){const t=document.createElement('div');t.className='toast';t.innerHTML=h;document.body.appendChild(t);return t}
async function buildPdf(src,ttl){const L=pdfLayout(src,ttl),imgs=[];try{for(const pg of L.pages)imgs.push(await pgJpeg(pg,1.5))}finally{L.host.remove()}return mkPdf(imgs)}
async function sharePdf(o){o=o||{};const src=o.src||$('#rp');if(!src)return;const t=toast('جاري تجهيز ملف PDF…');let blob;const n=(o.name||fname())+'.pdf';
 try{blob=await buildPdf(src,o.title)}catch(e){t.remove();console.error(e);if(confirm('تعذّر تجهيز ملف PDF على هذا الجهاز. أفتح نافذة الطباعة بدلًا منه (واختر حفظ كـ PDF)؟'))print();return}
 t.remove();const f=new File([blob],n,{type:'application/pdf'});
 const save=()=>{if(CAPN())return nativeSave(n,blob,'application/pdf');dl(n,blob,'application/pdf');alert('تم حفظ ملف PDF في مجلد التنزيلات: '+n)};
 EDTD=false;if(!(navigator.canShare&&navigator.canShare({files:[f]})))return save();
 try{await navigator.share({files:[f],title:n})}catch(e){if(e&&e.name=='AbortError')return;
  const r=toast(`<span>ملف PDF جاهز (${Math.round(blob.size/1024)} KB)</span><button class="pr" id="pdfgo">مشاركة الآن</button><button id="pdfdl">تنزيل</button><button id="pdfx">✕</button>`);
  r.querySelector('#pdfgo').onclick=async()=>{r.remove();try{await navigator.share({files:[f],title:n})}catch(er){if(!er||er.name!='AbortError')save()}};
  r.querySelector('#pdfdl').onclick=()=>{r.remove();save()};r.querySelector('#pdfx').onclick=()=>r.remove()}}
